	mm2Cuda(A, B, C, D, E, E_outputFromGpu);

	t_start = rtclock();
	mm2_cpu(A, B, C, D, E);
	t_end = rtclock();
	fprintf(stdout, "CPU Runtime: %0.6lfs\n", t_end - t_start);

	compareResults(E, E_outputFromGpu);

	free(C);
	free(A);
	free(B);
	free(D);
	free(E);
	free(E_outputFromGpu);

  	return ep_correctness_fail ? 2 : 0;
}

