int main(int argc,char** argv) {
  ScanProfileConfig config;
  if(!parse_scan_profile(argc,argv,config)) {
    fprintf(stderr,"Usage: %s --profile=short|hierarchical [--elements=262144|524288|1048576] [--seed=2009] [--iterations=1] [--device=0]; medium6815744 requires --allow-medium\n",argv[0]);
    return EXIT_FAILURE;
  }
  const uint N=config.elements, arrayLength=config.length;
  printf("SCAN_PROFILE_V1 profile=%s N=%u arrayLength=%u batch=%u seed=%u iterations=1 warmup=0 expected_kernels=%u\n",config.profile,N,arrayLength,N/arrayLength,config.seed,config.length==1024?1:3);
  findCudaDevice(argc,(const char**)argv);
