  srand(config.seed);
  for(uint i=0;i<N;i++) h_Input[i]=rand();
  // Lightweight provenance checksum, NOT a cryptographic input SHA or new oracle.
  uint64_t input_fnv64=14695981039346656037ULL;
  for(uint i=0;i<N;i++){uint x=h_Input[i];for(uint k=0;k<4;k++){input_fnv64^=(x>>(8*k))&255;input_fnv64*=1099511628211ULL;}}
  printf("INPUT_FNV1A64_NONCRYPTO=%016llx generator=libc_rand_unsigned32\n",(unsigned long long)input_fnv64);
  checkCudaErrors(cudaMalloc((void**)&d_Input,N*sizeof(uint)));
  checkCudaErrors(cudaMalloc((void**)&d_Output,N*sizeof(uint)));
  checkCudaErrors(cudaMemcpy(d_Input,h_Input,N*sizeof(uint),cudaMemcpyHostToDevice));
  initScan();
  int globalFlag=1;
  size_t szWorkgroup;
  // One selected whole scan, zero warmups and no timing repetition/sweep.
  if(config.length==1024) szWorkgroup=scanExclusiveShort(d_Output,d_Input,N/arrayLength,arrayLength);
  else szWorkgroup=scanExclusiveLarge(d_Output,d_Input,N/arrayLength,arrayLength);
  checkCudaErrors(cudaDeviceSynchronize());
    printf("Validating the results...\n");
    printf("...reading back GPU results\n");
    checkCudaErrors(cudaMemcpy(h_OutputGPU, d_Output, N * sizeof(uint),
                               cudaMemcpyDeviceToHost));

    printf(" ...scanExclusiveHost()\n");
    scanExclusiveHost(h_OutputCPU, h_Input, N / arrayLength, arrayLength);

    // Compare GPU results with CPU results and accumulate error for this test
    printf(" ...comparing the results\n");
    int localFlag = 1;

    for (uint i = 0; i < N; i++) {
      if (h_OutputCPU[i] != h_OutputGPU[i]) {
        localFlag = 0;
        break;
      }
    }

    // Log message on individual test result, then accumulate to global flag
    printf(" ...Results %s\n\n",
           (localFlag == 1) ? "Match" : "DON'T Match !!!");
    globalFlag = globalFlag && localFlag;


  printf("NATIVE_ORIGINAL_GOLD_QA=%s workgroup=%u\n",globalFlag?"PASS":"FAIL",(unsigned int)szWorkgroup);
  closeScan();checkCudaErrors(cudaFree(d_Output));checkCudaErrors(cudaFree(d_Input));
  free(h_Input);free(h_OutputCPU);free(h_OutputGPU);
  return globalFlag?EXIT_SUCCESS:EXIT_FAILURE;
}

