#ifndef SCAN_RESEARCH_PROFILE_CONFIG_V1
#define SCAN_RESEARCH_PROFILE_CONFIG_V1
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <climits>
struct ScanProfileConfig {
 const char* profile;
 std::uint32_t elements, length, seed, iterations;
 bool medium;
 ScanProfileConfig():profile(0),elements(1048576),length(0),seed(2009),iterations(1),medium(false){}
};
inline bool profile_uint(const char* s,std::uint32_t& out) {
 if(!s || !*s || *s=='-' || *s=='+') return false;
 for(const char* p=s;*p;++p) if(*p<'0'||*p>'9') return false;
 errno=0;char* e=0;unsigned long long v=std::strtoull(s,&e,10);
 if(errno || !e || *e || v>UINT32_MAX) return false;
 out=(std::uint32_t)v;return true;
}
inline bool parse_scan_profile(int argc,char** argv,ScanProfileConfig& c) {
 bool profile=false,elements=false,seed=false,iterations=false,allow=false,device=false;
 for(int i=1;i<argc;i++) {
  const char* a=argv[i];
  if(!std::strncmp(a,"--profile=",10)) {
   if(profile) return false;profile=true;
   if(!std::strcmp(a+10,"short")){c.profile="short";c.length=1024;}
   else if(!std::strcmp(a+10,"hierarchical")){c.profile="hierarchical";c.length=16384;}
   else return false;
  } else if(!std::strncmp(a,"--elements=",11)) {
   if(elements || !profile_uint(a+11,c.elements)) return false;elements=true;
  } else if(!std::strncmp(a,"--seed=",7)) {
   if(seed || !profile_uint(a+7,c.seed)) return false;seed=true;
  } else if(!std::strncmp(a,"--iterations=",13)) {
   if(iterations || !profile_uint(a+13,c.iterations) || c.iterations!=1) return false;iterations=true;
  } else if(!std::strcmp(a,"--allow-medium")) {
   if(allow) return false;allow=true;c.medium=true;
  } else if(!std::strcmp(a,"--device=0")) {
   if(device) return false;device=true;
  } else return false;
 }
 if(!profile || c.iterations!=1) return false;
 const bool small=(c.elements==262144 || c.elements==524288 || c.elements==1048576);
 if(!small && !(c.medium && c.elements==6815744)) return false;
 if(c.elements%1024 || c.elements%c.length || c.elements>67108864) return false;
 return true;
}
#endif

